"""Create the demonstration dataset used by the resume classification project."""

from __future__ import annotations

import base64
import gzip
from pathlib import Path

DATASET_GZIP_BASE64 = ""

BASE_DIR = Path(__file__).resolve().parent
DEFAULT_DATASET_PATH = BASE_DIR / "resume_dataset.csv"


def ensure_dataset(path: str | Path | None = None) -> Path:
    """Return a usable dataset path, recreating the demo CSV when necessary."""
    output_path = Path(path) if path is not None else DEFAULT_DATASET_PATH

    if not output_path.exists():
        dataset_bytes = gzip.decompress(
            base64.b64decode(DATASET_GZIP_BASE64)
        )
        output_path.write_bytes(dataset_bytes)

    return output_path


if __name__ == "__main__":
    path = ensure_dataset()
    print(f"Dataset available at: {path}")
